import { InputEngineEvent } from "#core/ui/input/input-support.js";
import NavTray from "#core/ui/navigation-tray/model-navigation-tray.js";
import Panel from "#core/ui/panel-support.js";
import { MustGetElement } from "#core/ui/utilities/utilities-dom.js";
import { NetworkUtilities } from "#core/ui/utilities/utilities-network.js";
import { FocusManager } from "#core/ui-next/services/focus-manager.js";

import content from "#core/ui/shell/mp-account-permissions/mp-account-permissions.html?raw";
import styles from "#core/ui/shell/mp-account-permissions/mp-account-permissions.scss?url";

class MpAccountPermissions extends Panel {
	private engineInputListener = this.onEngineInput.bind(this);

	private qrCodeImage: HTMLElement;
	private qrCodeText: HTMLElement;

	private locKey: string = "LOC_UI_PERMISSION_CHANGE_REQUIRED";
	private customUrl: string | null = "https://portal.2k.com/2k/portal/game-permissions";
	private blockReason: BlockedAccessReason = BlockedAccessReason.NONE;

	constructor(root: ComponentRoot) {
		super(root);

		this.qrCodeImage = MustGetElement(".qr-code-image", this.Root);
		this.qrCodeText = MustGetElement(".qr-code-text", this.Root);
	}

	onInitialize(): void {
		super.onInitialize();

		this.Root.classList.add(
			"mp-account-permissions",
			"absolute",
			"inset-0",
			"flex",
			"flex-row",
			"justify-center",
			"items-center",
		);
	}

	onAttach() {
		super.onAttach();

		const connStatus = document.querySelector<HTMLElement>(".connection-status");
		connStatus?.classList.add("no-mouse");

		const frame = MustGetElement(".mp-account-permissions__main-content", this.Root);

		this.Root.addEventListener("engine-input", this.engineInputListener);

		const closeButton: HTMLElement = document.createElement("fxs-close-button");
		closeButton.classList.add("top-4", "-right-12");
		closeButton.addEventListener("action-activate", () => {
			this.close();
		});
		frame.appendChild(closeButton);

		this.renderContent();
	}

	onDetach() {
		this.Root.removeEventListener("engine-input", this.engineInputListener);

		const connStatus = document.querySelector<HTMLElement>(".connection-status");
		if (connStatus) {
			connStatus.classList.remove("no-mouse");
		}

		super.onDetach();
	}

	onReceiveFocus() {
		super.onReceiveFocus();

		FocusManager.get().setFocus(this.Root);

		NavTray.clear();
		NavTray.addOrUpdateGenericBack();
	}

	onLoseFocus() {
		NavTray.clear();

		super.onLoseFocus();
	}

	override onAttributeChanged(name: string, _oldValue: string | null, newValue: string | null): void {
		switch (name) {
			case "loc-key":
				this.locKey = newValue && newValue.length > 0 ? newValue : "LOC_UI_PERMISSION_CHANGE_REQUIRED";
				break;
			case "portal-url":
				this.customUrl = newValue && newValue.length > 0 ? newValue : null;
				break;
			case "block-reason": {
				const parsedReason = Number(newValue);
				this.blockReason = Number.isNaN(parsedReason) ? BlockedAccessReason.NONE : (parsedReason as BlockedAccessReason);
				break;
			}
			default:
				break;
		}

		if (this.Root.isConnected) {
			this.renderContent();
		}
	}

	private renderContent() {
		this.renderQrImage();
		this.renderQrLink();
	}

	private renderQrImage() {
		if (!this.qrCodeImage) {
			console.error("mp-account-permissions: qr-code-image is missing");
			return;
		}

		if (this.blockReason == BlockedAccessReason.CHILD_PERMISSION_DENIED || this.blockReason == BlockedAccessReason.CHILD_PURCHASE_DENIED) {
			// TBD: Do we want to show any separate QR for child permission cases?
			this.qrCodeImage.style.backgroundImage = "";
			this.qrCodeImage.innerHTML = "";
			return;
		}

		const PERMISSIONS_QR_URL = "fs://game/PortalAccountPermissionsQRCode.png";
		const FALLBACK_QR_URL = "fs://game/UnlinkPortalQRCode.png";
		const shouldUseVerificationUrl = NetworkUtilities.requiresAccountValidation(this.blockReason);
		const QRToShow = shouldUseVerificationUrl ? FALLBACK_QR_URL : PERMISSIONS_QR_URL;
		const imgElement = document.createElement("img");
		imgElement.style.width = "100%";
		imgElement.style.height = "100%";
		imgElement.onerror = () => {
			// If cannot load permissions QR, tries the fallback QR, and if still not doesn't show QR
			if (imgElement.src.endsWith("UnlinkPortalQRCode.png")) {
				console.error("mp-account-permissions: couldn't load a local QR code image");
				this.qrCodeImage.style.backgroundImage = "";
				this.qrCodeImage.innerHTML = "";
				return;
			}
			imgElement.src = FALLBACK_QR_URL;
		};
		this.qrCodeImage.innerHTML = "";
		this.qrCodeImage.appendChild(imgElement);
		imgElement.src = QRToShow;
	}

	private renderQrLink() {
		if (!this.qrCodeText) {
			console.error("mp-account-permissions: qr-code-text is missing");
			return;
		}

		let displayedUrl = this.customUrl;
		if (!displayedUrl || displayedUrl.length == 0) {
			displayedUrl = NetworkUtilities.requiresAccountValidation(this.blockReason)
				? Network.getQrVerificationUrl()
				: Network.getQrTwoKPermissionsUrl();
		}

		if (!displayedUrl || displayedUrl.length == 0) {
			displayedUrl = Locale.compose("LOC_UI_LINK_ACCOUNT_QR_CODE_FETCH_FAILURE");
		}

		const firstPartyType: HostingType = Network.getLocalHostingPlatform();
		const isPCPlatform: boolean =
			firstPartyType == HostingType.HOSTING_TYPE_STEAM || firstPartyType == HostingType.HOSTING_TYPE_EOS;

		const url = isPCPlatform
			? '<span class="clickable-link">' + displayedUrl + "</span>"
			: displayedUrl;

		if (this.locKey === "LOC_UI_PERMISSION_CHANGE_REQUIRED")
		{
			// to display a more detailed permissions message with url
			this.qrCodeText.innerHTML = Locale.compose("LOC_UI_GO_TO_PORTAL_PERMISSIONS", url);

			this.qrCodeText.addEventListener("click", () => {
					Network.openTwoKPermissionsURL();
			});
		}
		else
		{
			// other messages have already been piped through blockInfo
			this.qrCodeText.innerHTML = Locale.compose(this.locKey);
		}
	}

	private onEngineInput(inputEvent: InputEngineEvent) {
		if (inputEvent.detail.status != InputActionStatuses.FINISH) {
			return;
		}

		if (inputEvent.isCancelInput()) {
			this.close();
			inputEvent.stopPropagation();
			inputEvent.preventDefault();
		}
	}
}

declare global {
	interface HTMLElementTagNameMap {
		"screen-mp-account-permissions": ComponentRoot<MpAccountPermissions>;
	}
}

Controls.define("screen-mp-account-permissions", {
	createInstance: MpAccountPermissions,
	description: "Screen for account portal permissions messaging.",
	styles: [styles],
	innerHTML: [content],
	attributes: [{ name: "loc-key" }, { name: "portal-url" }, { name: "block-reason" }],
	tabIndex: -1,
});
